"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[31864],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>d});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},43365:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>h,contentTitle:()=>d,default:()=>c,frontMatter:()=>a,metadata:()=>r,toc:()=>o});const r=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"De-Stressing Booking.com","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/de/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17. April 2023","top_news":"De-Stressing Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/de/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/de/2023/04/16"}}');var t=i(23420),s=i(3331);const a={localized_date:"17. April 2023",top_news:"De-Stressing Booking.com"},d="2023-04-17",h={},o=[{value:"De-Stressing Booking.com",id:"de-stressing-bookingcom",level:2},{value:"Ich habe Stable Diffusion und Dreambooth verwendet, um ein Kunstportr\xe4t meines Hundes zu erstellen.",id:"ich-habe-stable-diffusion-und-dreambooth-verwendet-um-ein-kunstportr\xe4t-meines-hundes-zu-erstellen",level:2},{value:"AT&amp;T Wireless Traffic Shaping macht offenbar einige Websites unbrauchbar",id:"att-wireless-traffic-shaping-macht-offenbar-einige-websites-unbrauchbar",level:2},{value:"Future Blues - Emilys Cowboy Bebop Seite (1999)",id:"future-blues---emilys-cowboy-bebop-seite-1999",level:2},{value:"Sp\xfclmaschinenlachs",id:"sp\xfclmaschinenlachs",level:2},{value:"Pico3D: Open World 3D Game Engine f\xfcr das PicoSystem (RP2040 Mikrocontroller)",id:"pico3d-open-world-3d-game-engine-f\xfcr-das-picosystem-rp2040-mikrocontroller",level:2},{value:"Wayback: Selbstgehosteter Archivierungsdienst, integriert mit Internet Archive",id:"wayback-selbstgehosteter-archivierungsdienst-integriert-mit-internet-archive",level:2},{value:"Die schnellste mathematische Satzbibliothek f\xfcr das Web",id:"die-schnellste-mathematische-satzbibliothek-f\xfcr-das-web",level:2},{value:"&#39;Algebra f\xfcr alle&#39; scheitert in San Francisco",id:"algebra-f\xfcr-alle-scheitert-in-san-francisco",level:2},{value:"FSF kritisiert Google wegen der Abschaffung von JPEG-XL in Chrome",id:"fsf-kritisiert-google-wegen-der-abschaffung-von-jpeg-xl-in-chrome",level:2}];function u(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,t.jsx)(n.h2,{id:"de-stressing-bookingcom",children:"De-Stressing Booking.com"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Original"}),'.\nDer Autor teilt einen Meinungsartikel \xfcber den \xfcberm\xe4\xdfigen Einsatz von \xdcberredungstaktiken auf E-Commerce-Websites, insbesondere Booking.com, und stellt seine Chrome-Erweiterung "De-stresser" vor, die stressverursachende Nachrichten und Benachrichtigungen von Booking.com entfernt und den Benutzern ein angenehmeres Erlebnis bietet. Durch das Ausblenden von \xdcberredungs-Tags und die Anpassung der Sprache an einen positiveren Klang erm\xf6glicht der De-stresser ein ruhigeres und entspannteres Buchungserlebnis f\xfcr die Nutzer. Die Erweiterung ist jetzt live und kann auf Booking.com genutzt werden.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),'.\nBooking.com sieht sich mit Kritik konfrontiert, weil das Unternehmen Verkaufsstrategien mit hohem Druck einsetzt, einschlie\xdflich Dringlichkeitsnachrichten und Pop-ups, die Nutzer abschrecken k\xf6nnen. Kritiker argumentieren, dass dieser Ansatz kurzfristigen Kennzahlen Vorrang vor langfristiger Kundentreue einr\xe4umt. Nutzer berichten, dass sie Wege gefunden haben, diese Taktiken zu umgehen, einschlie\xdflich der Verwendung von Erweiterungen, um sie zu blockieren oder zu filtern. In der Zwischenzeit diskutieren Discussion Service-Nutzer \xfcber die Vorz\xfcge von A/B-Tests, wobei einige auf das Potenzial hinweisen, "dunkle Muster" auf Websites zu erzeugen. Trotz dieser Bedenken nutzen viele Nutzer weiterhin Buchungsaggregatoren wie Booking.com und Expedia, entweder aus Bequemlichkeit oder weil sie g\xfcnstige Preise und Stornierungsbedingungen bieten. Einige Experten weisen darauf hin, dass die Buchung direkt beim Hotel bessere M\xf6glichkeiten zur Beilegung von Streitigkeiten bietet, w\xe4hrend andere darauf hinweisen, dass die Provisionss\xe4tze f\xfcr Buchungsseiten je nach Hotel sehr unterschiedlich sein k\xf6nnen. Nichtsdestotrotz k\xf6nnen Treueprogramme von Hotels f\xfcr Vielreisende erhebliche Vorteile bieten.']}),"\n",(0,t.jsx)(n.h2,{id:"ich-habe-stable-diffusion-und-dreambooth-verwendet-um-ein-kunstportr\xe4t-meines-hundes-zu-erstellen",children:"Ich habe Stable Diffusion und Dreambooth verwendet, um ein Kunstportr\xe4t meines Hundes zu erstellen."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"Original"}),".\nDer Artikel beschreibt die Verwendung von Stable Diffusion und Dreambooth AI-Techniken, um ein hochwertiges gemaltes Portr\xe4t eines Hundes zu erstellen. Der Autor teilt seinen gesamten Arbeitsablauf mit und gibt detaillierte Anweisungen, wie man ein Dreambooth-Modell auf Fotos seines Hundes trainiert. Der Artikel beschreibt auch die Verwendung von Upscaling, um kleine Bilder f\xfcr qualitativ hochwertige Drucke zu vergr\xf6\xdfern, und stellt Stable Diffusion als einen Wendepunkt in der Welt der generativen Text-zu-Bild-Kunst vor."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nEin Discussion Service-Benutzer verwendete Stable Diffusion und Dreambooth, um ein Kunstportr\xe4t seines Hundes zu erstellen, w\xe4hrend in den Kommentaren der Widerstand gegen KI-Kunst und Debatten \xfcber Urheberrecht und faire Nutzung diskutiert wurden. Die Verwendung generativer KI f\xfcr Kunst wirft ethische Fragen in Bezug auf das Urheberrecht und die faire Nutzung auf, wobei die Meinungen zu diesem Thema geteilt sind. Einige kritisierten, dass Stable Diffusion unentgeltlich gestohlene Kunstwerke als Trainingsdaten verwendet, w\xe4hrend andere die Technologie und ihr Potenzial f\xfcr weitere Innovationen in diesem Bereich lobten."]}),"\n",(0,t.jsx)(n.h2,{id:"att-wireless-traffic-shaping-macht-offenbar-einige-websites-unbrauchbar",children:"AT&T Wireless Traffic Shaping macht offenbar einige Websites unbrauchbar"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Original"}),'.\nAT&Ts "unbegrenzter" 100Mbit-Tarif mit 50GB f\xfcr priorisierte Daten kann aggressiv Traffic Shaping betreiben, was dazu f\xfchrt, dass einige Websites unbrauchbar sind, w\xe4hrend ein Test zeigte, dass eine Verizon-SIM-Karte das gleiche Problem nicht hatte. Der Datenverkehr von Akamai zeigt Anzeichen f\xfcr eine absichtliche Manipulation des TCP-Streams. Traffic Shaping betrifft nur die reinen Datenkonten von Gesch\xe4ftskunden.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nAT&T Wireless drosselt Berichten zufolge IP-Adressen f\xfcr einige Video-Streaming-Sites, wodurch einige Websites unbrauchbar werden und Diskrepanzen bei Internet-Geschwindigkeitstests auftreten. Benutzer haben L\xf6sungen vorgeschlagen, wie das Einreichen einer FCC-Beschwerde, die Verwendung eines VPN zur Umgehung der Drosselung oder das Ausprobieren eines anderen APN. Einige Kommentatoren sind skeptisch, ob hinter der Drosselung ruchlose Absichten stecken, w\xe4hrend andere L\xf6sungen wie Geschwindigkeitsbegrenzungen oder die Herabsetzung der Videoqualit\xe4t vorschlagen, um das Datenkontingent zu erhalten."]}),"\n",(0,t.jsx)(n.h2,{id:"future-blues---emilys-cowboy-bebop-seite-1999",children:"Future Blues - Emilys Cowboy Bebop Seite (1999)"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://futureblues.com/",children:"Original"}),".\nLeider gibt es keinen Text, den ich zusammenfassen k\xf6nnte."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nDiscussion Service-Benutzer dr\xfccken ihre Sehnsucht nach dem originellen und kreativen Design klassischer Websites aus und kontrastieren sie mit der standardisierten, lauten und monetarisierten Natur moderner Websites, was auf eine Sehnsucht nach k\xfcnstlerischeren, auf Individualit\xe4t ausgerichteten Medienlandschaften schlie\xdfen l\xe4sst. Diskussionspunkte ergeben sich aus dem Vergleich von Wikipedia und Fandom und der Unterscheidung zwischen mobilen und reinen Desktop-Websites, und das Design der Website weckt sowohl Nostalgie als auch Erstaunen \xfcber ihre Langlebigkeit. Insgesamt bietet der Beitrag einen Einblick in die sch\xf6nen Erinnerungen der Nutzer an die Anf\xe4nge des Internets und bietet eine Plattform f\xfcr die Diskussion \xfcber den aktuellen Zustand des Webs."]}),"\n",(0,t.jsx)(n.h2,{id:"sp\xfclmaschinenlachs",children:"Sp\xfclmaschinenlachs"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Original"}),".\nSp\xfclmaschinenlachs ist ein Fischgericht, das hergestellt wird, indem Lachsst\xfccke in mindestens zwei Lagen Alufolie eingewickelt und w\xe4hrend des Wasch- und Trockengangs in die Sp\xfclmaschine gegeben werden. Die Methode wurde erstmals 1975 in den USA von Vincent Price vorgestellt und ist seitdem in verschiedenen Medien zu sehen. Es gibt jedoch Bedenken hinsichtlich der Temperaturkonstanz in Geschirrsp\xfclern, die zu unvollst\xe4ndigem Garen und m\xf6glichen Gesundheitsrisiken f\xfchren kann."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nEin Artikel von Hacker News \xfcber das Garen von Lachs in der Sp\xfclmaschine entfacht eine Debatte \xfcber die Sicherheit dieser Garmethode, wobei Nutzer aus der Lebensmittelsicherheitsbranche den Behauptungen eines YouTubers widersprechen. Die Sicherheit des Kochens in der Sp\xfclmaschine h\xe4ngt zwar von mehreren Faktoren ab, aber mindestens 63 \xb0C f\xfcr 15 Sekunden ist erforderlich, um Bakterien im Lachs abzut\xf6ten."]}),"\n",(0,t.jsx)(n.h2,{id:"pico3d-open-world-3d-game-engine-f\xfcr-das-picosystem-rp2040-mikrocontroller",children:"Pico3D: Open World 3D Game Engine f\xfcr das PicoSystem (RP2040 Mikrocontroller)"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Original"}),".\nDie Pico3D-Spiele-Engine nutzt den zweiten Kern des RP2040 als dedizierten Rasterizer/GPU, um ein komplettes Open-World-3D-Spiel auf einem 1-Dollar-Mikrocontroller laufen zu lassen. Die Engine enth\xe4lt eine kleine Stadt und Au\xdfenbezirke mit schie\xdfbaren Zombies, wobei Blender-Tutorials zur Erstellung von Spielwelten zur Verf\xfcgung stehen. Die Simulation der Engine umfasst derzeit 50 NPCs und 50 Zombies gleichzeitig, wobei das Rendering durch Distanz- und View Frustum Culling optimiert wird."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nEine neue 3D-Spiele-Engine namens Pico3D wurde f\xfcr den RP2040-Mikrocontroller mit einem 120x120px-Display entwickelt, dem es an Speicher und Video-RAM mangelt, der aber \xfcber eine einheitliche API verf\xfcgt. Hacker sind begeistert von den kreativen M\xf6glichkeiten, den Pico/RP2040 zu nutzen, und die einzigartige Anwendung von RAM-Chips im Framebuffer macht diesen Artikel auf der Tech-Site besonders interessant."]}),"\n",(0,t.jsx)(n.h2,{id:"wayback-selbstgehosteter-archivierungsdienst-integriert-mit-internet-archive",children:"Wayback: Selbstgehosteter Archivierungsdienst, integriert mit Internet Archive"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/wabarc/wayback",children:"Original"}),".\nWayback ist ein selbstgehostetes Archivierungstool, mit dem Webseiten in Zeitkapseln festgehalten werden k\xf6nnen. Es ist kostenlos, quelloffen, plattform\xfcbergreifend und erm\xf6glicht eine einfachere Integration in verschiedene Plattformen, darunter das Internet Archive, archive.today, IPFS und Telegraph. Au\xdferdem bietet es mehrere Installationsoptionen, darunter \xfcber GitHub, Snapcraft, APT, RPM und Homebrew."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),'.\nDer selbst gehostete Archivierungsdienst Wabarc erstellt Schnappsch\xfcsse von Webseiten in "Zeitkapseln" und speichert Dateien zur Offline-Nutzung; Discussion Service-Nutzer kritisieren jedoch die unklare README und die fehlende Dokumentation. Andere \xe4hnliche Projekte sind ArchiveBox, Shiori, DiskerNet und SingleFile; HTTrack Website Copier wird empfohlen, um eine ganze Website lokal herunterzuladen, w\xe4hrend Browsertrix/Brozzler mit Headless Browsern auf Genauigkeit crawlt. Ein Discussion Service-Nutzer empfiehlt The Old Net f\xfcr das Browsen mit alten/modernen Browsern ohne JS, und das verlinkte Repo ben\xf6tigt mehr Klarheit \xfcber die Teilbarkeit und etablierte Archivierungsstandards.']}),"\n",(0,t.jsx)(n.h2,{id:"die-schnellste-mathematische-satzbibliothek-f\xfcr-das-web",children:"Die schnellste mathematische Satzbibliothek f\xfcr das Web"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://katex.org/",children:"Original"}),".\nKaTeX ist eine schnelle mathematische Satzbibliothek f\xfcr das Web, die ein Layout in Druckqualit\xe4t auf der Grundlage von Donald Knuths TeX bietet, keine Abh\xe4ngigkeiten hat und leicht mit Website-Ressourcen f\xfcr serverseitiges Rendering mit Node.js geb\xfcndelt werden kann. Die einfache API rendert mathematische Ausdr\xfccke effizient, sogar auf Seiten mit mehreren Ausdr\xfccken, ohne Browser- oder Umgebungseinschr\xe4nkungen, und ist Open Source unter der MIT-Lizenz."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, die schnellste mathematische Satzbibliothek f\xfcr das Web, unterst\xfctzt keine Diagramme, was sie f\xfcr einige Mathematiker ungeeignet macht, w\xe4hrend MathJax und AsciiMath beide \xe4hnliche Projekte haben. Eine Vergleichswebseite wurde geteilt, und die Leistung und Praktikabilit\xe4t der Anpassung von Markup an verschiedene Kontexte wird von den Nutzern von Hacker News diskutiert."]}),"\n",(0,t.jsx)(n.h2,{id:"algebra-f\xfcr-alle-scheitert-in-san-francisco",children:"'Algebra f\xfcr alle' scheitert in San Francisco"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"Original"}),'.\nLaut einer Studie von Stanford-Professoren hat die "Algebra for none"-Politik des Schulbezirks San Francisco Unified die Leistungen schwarzer und hispanischer Sch\xfcler in fortgeschrittener Mathematik nicht verbessert, was zu einer zunehmenden Leistungsl\xfccke f\xfchrte. Die Entscheidung, Algebra bis zur neunten Klasse hinauszuz\xf6gern und leistungsschwache und leistungsstarke Sch\xfcler in dieselben Klassen zu schicken, hat leistungsschwachen Sch\xfclern nicht geholfen und es leistungsstarken Sch\xfclern schwerer gemacht, erfolgreich zu sein. Familien, die es sich leisten k\xf6nnen, haben sich f\xfcr Online-Kurse oder Privatschulen entschieden. Eine Gruppe von Eltern hat eine Klage gegen den Bezirk eingereicht und behauptet, dies versto\xdfe gegen das staatliche Gesetz \xfcber den gleichberechtigten Zugang zu fortgeschrittener Mathematik.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nSan Franciscos Politik, Algebra bis zur 9. Klasse hinauszuz\xf6gern und leistungsschwache, durchschnittliche und leistungsstarke Sch\xfcler in dieselben Klassen zu schicken, wurde kritisiert, wobei einige vorschlugen, dass grundlegende mathematische Konzepte fr\xfcher unterrichtet werden sollten. Einige Discussion Service-Nutzer schlagen vor, Anreize f\xfcr akademischen und au\xdferschulischen Erfolg zu schaffen, indem man ihn mit einer finanziellen Belohnung verkn\xfcpft, w\xe4hrend andere argumentieren, dass die Subventionierung der Hochschulbildung durch Kreditsysteme, mit denen man sp\xe4ter f\xfcr das College bezahlen kann, eine bessere L\xf6sung w\xe4re. Es gibt Debatten \xfcber die N\xfctzlichkeit des traditionellen Mathematikunterrichts und die Wirksamkeit einer Aufstockung der Mittel zur Verringerung der Klassengr\xf6\xdfen, wobei einige Nutzer vorschlagen, Mathematik anhand von technischen Problemen und den Vorteilen der Online-Bildung zu unterrichten."]}),"\n",(0,t.jsx)(n.h2,{id:"fsf-kritisiert-google-wegen-der-abschaffung-von-jpeg-xl-in-chrome",children:"FSF kritisiert Google wegen der Abschaffung von JPEG-XL in Chrome"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"Original"}),".\nDie Free Software Foundation (FSF) kritisiert Googles Entscheidung, die JPEG-XL-Unterst\xfctzung in Chrome zu streichen, und unterstreicht die Notwendigkeit von Browserwahl und freien Medienformaten. Trotz der Aufregung in der Community haben die Google-Ingenieure diese Entscheidung getroffen, die zu den am meisten beachteten Problemen in der Geschichte des Chromium-Projekts geh\xf6rt. Die Nutzer haben JPEG-XL stark unterst\xfctzt, aber Googles Fokus auf Kontrolle statt Freiheit scheint zu \xfcberwiegen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nGoogle wird von der Free Software Foundation daf\xfcr kritisiert, dass es die Unterst\xfctzung f\xfcr JPEG-XL in Chrome eingestellt hat, obwohl es von wichtigen Bildbearbeitungsprogrammen \xfcbernommen wurde. Einige Nutzer argumentieren, dass \xe4ltere Formate wie PNG und JPEG ausreichend sind, w\xe4hrend andere Codecs wie AVIF f\xfcr Videos bevorzugen. Die Debatte dreht sich um die Realisierbarkeit und Akzeptanz neuer Bildformate im \xd6kosystem. Die Industrie unterst\xfctzt und interessiert sich f\xfcr JPEG-XL, aber die Akzeptanz h\xe4ngt davon ab, dass es von allen gro\xdfen Browsern unterst\xfctzt wird."]})]})}function c(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(u,{...e})}):u(e)}}}]);